'use strict';
const screens=[['splash','Splash','آغاز'],['onboarding','Onboarding','آشنایی'],['home','Dashboard','خانه'],['training','Training selection','انتخاب تمرین'],['vision','Vision overview','دیداری'],['vision-exercise','Vision exercise','تمرین دیداری'],['reflex','Reflex overview','واکنش'],['reflex-exercise','Reflex exercise','تمرین واکنش'],['read','Reading overview','خواندن'],['reading-player','Reading player','پخش خواندن'],['type','Typing overview','تایپ'],['typing-exercise','Typing exercise','تمرین تایپ'],['result','Session report','گزارش جلسه'],['insights','Statistics','تحلیل'],['achievements','Achievements','دستاوردها'],['library','Training library','کتابخانه'],['profile','Profile','پروفایل'],['settings','Settings','تنظیمات'],['vault','Backup & restore','پشتیبان و بازیابی'],['states','Error & empty states','خطا و دادهٔ خالی']];
let language='en',filter='all',query='';
const t=(en,fa)=>language==='fa'?fa:en;
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={home:'<path d="m3 11 9-8 9 8M5 10v11h14V10M10 21v-7h4v7"/>',training:'<rect x="3" y="3" width="7" height="7"/><rect x="14" y="3" width="7" height="7"/><rect x="3" y="14" width="7" height="7"/><rect x="14" y="14" width="7" height="7"/>',vision:'<ellipse cx="12" cy="12" rx="10" ry="6"/><circle cx="12" cy="12" r="3"/>',reflex:'<path d="m14 2-9 12h6l-1 8L20 9h-6Z"/>',read:'<rect x="3" y="4" width="18" height="16" rx="2"/><path d="M12 4v16M6 8h3m6 0h3M6 12h3m6 0h3"/>',type:'<rect x="2" y="5" width="20" height="14" rx="2"/><path d="M6 9v1m4-1v1m4-1v1m4-1v1M6 13v1m4-1v1m4-1v1m4-1v1m-10 3h8"/>',insights:'<path d="M4 20h17M5 16v-4m6 4V7m6 9V3"/>',library:'<path d="M4 4h5v17H4zm7 0h5v17h-5zm7 1 3-1 4 16-3 1Z"/>',profile:'<circle cx="12" cy="7" r="4"/><path d="M4 21a8 8 0 0 1 16 0"/>'};
const icon=id=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[id]||icons.training}</svg>`;
const sample=()=>`<p class="sample">${t('ILLUSTRATIVE DESIGN CONTENT · NOT MEASURED DATA','دادهٔ نمونهٔ طراحی · نه اندازه‌گیری واقعی')}</p>`;
const button=(label,go,secondary=false)=>`<button class="button${secondary?' secondary':''}" data-go="${go}">${label}<span aria-hidden="true">${language==='fa'?'←':'→'}</span></button>`;
const title=(label,heading,body='')=>`<div><p class="eyebrow">${label}</p><h1>${heading}</h1>${body?`<p>${body}</p>`:''}</div>`;
const metric=(value,label,unit='')=>`<div class="metric"><strong>${value}<em>${unit}</em></strong><small>${label}</small></div>`;
const section=(name,note='')=>`<div class="section-head"><h3>${name}</h3><span>${note}</span></div>`;
const modules=[['vision','01','See with intention.','دیدن با تمرکز','Visual attention','توجه دیداری',3],['reflex','02','Make your move.','پاسخ دقیق‌تر','Response & control','واکنش و کنترل',5],['read','03','Read. Understand.','بخوان و درک کن','Pace & comprehension','سرعت و درک',3],['type','04','Precision in every key.','دقت در هر کلید','Accuracy & fluency','دقت و روانی',3]];
const exercises=[['vision','Focus Lock','قفل تمرکز'],['vision','Visual Search','جست‌وجوی دیداری'],['vision','Pattern Match','تطبیق الگو'],['reflex','Quick Tap','واکنش سریع'],['reflex','Go / No-Go','برو / نرو'],['reflex','Shape Reaction','واکنش به شکل'],['reflex','Color Reaction','واکنش به رنگ'],['reflex','Direction Match','تطبیق جهت'],['read','Comprehension','درک مطلب'],['read','Phrase Reading','خواندن عبارت'],['read','RSVP Reader','خواندن تک‌واژه'],['type','Key Precision','دقت تایپ'],['type','Word Sprint','تایپ واژه'],['type','Code Typing','تایپ کد']];
function moduleCards(){return `<div class="module-grid">${modules.map(([id,num,en,fa,desc,descfa,count])=>`<button class="module" data-module="${id}" data-go="${id}"><span class="arrow" aria-hidden="true">↗</span>${icon(id)}<span class="id">${num} / ${id.toUpperCase()}</span><strong>${t(en,fa)}</strong><small>${t(desc,descfa)} · ${count}</small></button>`).join('')}</div>`;}
function week(){return `<div class="week" role="img" aria-label="${t('Illustrative weekly minutes: 12, 8, 0, 15, 6, 10, 0','دقایق نمونهٔ هفته: ۱۲، ۸، ۰، ۱۵، ۶، ۱۰، ۰')}">${[12,8,0,15,6,10,0].map((v,i)=>`<div class="day"><div class="bar ${v?'done':''}" style="--height:${v*4+3}px"></div><span>${t(['M','T','W','T','F','S','S'][i],['د','س','چ','پ','ج','ش','ی'][i])}</span></div>`).join('')}</div>`;}
function art(id){let paths={vision:'<ellipse cx="160" cy="60" rx="118" ry="42"/><ellipse cx="160" cy="60" rx="80" ry="42"/><circle cx="160" cy="60" r="26"/><path d="M10 60h300M160 8v104"/>',reflex:'<path d="M10 62h65l15-31 25 65 34-83 30 67 18-18h113"/><path opacity=".3" d="M10 25h300M10 100h300"/>',read:'<path d="M25 26h270M25 48h270M25 70h270M25 92h270" opacity=".3"/><path d="M65 48h190M110 70h100" stroke-width="4"/>',type:'<path d="M22 25h276v70H22ZM35 42h250M35 64h250M85 80h150"/><path opacity=".4" d="M65 25v50M105 25v50M145 25v50M185 25v50M225 25v50M265 25v50"/>'};return `<svg class="line-art" viewBox="0 0 320 120" aria-hidden="true">${paths[id]}</svg>`;}
function overview(id){let m=modules.find(x=>x[0]===id),items=exercises.filter(x=>x[0]===id);return `<div class="module-${id}">${title(`${m[1]} / ${id.toUpperCase()} STUDIO`,t(m[2],m[3]),t(m[4],m[5]))}</div><div class="panel module-${id}">${art(id)}<div class="metrics">${metric(id==='reflex'?'284':id==='read'?'186':id==='type'?'42':'91',t('Recent measure','اندازه‌گیری اخیر'),id==='reflex'?'ms':id==='read'||id==='type'?'WPM':'%')}${metric('06',t('Valid sessions','جلسهٔ معتبر'))}</div>${sample()}</div>${section(t('Your next practice','تمرین بعدی شما'),t('Manual override always available','انتخاب دستی آزاد است'))}<div class="panel"><span class="pill gold">${t('WHY THIS EXERCISE','دلیل این پیشنهاد')}</span><h2>${t(items[0][1],items[0][2])}</h2><p>${t('A short, familiar session. Keep this level until enough valid history supports a change.','یک جلسهٔ کوتاه و آشنا. تا ثبت سابقهٔ معتبر کافی، سطح فعلی حفظ می‌شود.')}</p>${button(t('View exercise layout','نمایش طراحی تمرین'),id==='read'?'reading-player':id==='type'?'typing-exercise':`${id}-exercise`)}</div>${section(t('Explore the studio','تمرین‌های این بخش'),`${items.length} ${t('available','تمرین موجود')}`)}<div>${items.map(([mid,en,fa],i)=>`<div class="list-item module-${id}"><span class="tag-icon">${String(i+1).padStart(2,'0')}</span><div class="copy"><h3>${t(en,fa)}</h3><small>${en==='Comprehension'?t('Instructions · fixed level 1 · local history','راهنما · سطح ثابت ۱ · تاریخچهٔ محلی'):t('Instructions · adjustable level · local history','راهنما · سطح قابل تنظیم · تاریخچهٔ محلی')}</small></div><button data-go="${id==='read'?'reading-player':id==='type'?'typing-exercise':id+'-exercise'}" aria-label="${escape(t(en,fa))}">↗</button></div>`).join('')}</div><p>${id==='vision'?t('Comfort first. Stop if you feel discomfort. Not medical treatment.','آسایش چشم مهم است. در صورت ناراحتی توقف کنید. این تمرین درمان پزشکی نیست.'):t('Results describe this task only, not general intelligence.','نتیجه فقط به همین تکلیف مربوط است، نه هوش عمومی.')}</p>`;}
function library(){let items=exercises.filter(x=>(filter==='all'||filter===x[0])&&`${x[1]} ${x[2]}`.toLowerCase().includes(query.toLowerCase()));return `${title('YOUR TRAINING COLLECTION',t('Find your focus.','تمرین مناسب شما.'),t('Four systems. One considered practice.','چهار سیستم. یک تمرین هدفمند.'))}<input class="input" id="search" aria-label="${t('Search exercises','جست‌وجوی تمرین')}" placeholder="${t('Search your exercises…','جست‌وجوی تمرین…')}" value="${escape(query)}"><div class="chips">${['all','vision','reflex','read','type'].map(x=>`<button class="chip ${x===filter?'active':''}" data-filter="${x}">${x==='all'?t('All systems','همه'):x.toUpperCase()}</button>`).join('')}</div>${section(`${items.length} ${t('exercises','تمرین')}`)}<div>${items.map(([id,en,fa])=>`<div class="list-item module-${id}"><span class="tag-icon">${icon(id)}</span><div class="copy"><h3>${t(en,fa)}</h3><small>${id.toUpperCase()} · ${en==='Comprehension'?t('Fixed level 1','سطح ثابت ۱'):t('Levels 1–5','سطح ۱ تا ۵')}</small></div><button data-go="${id}" aria-label="${escape(t(en,fa))}">↗</button></div>`).join('')||`<div class="panel"><h3>${t('No matching exercises','تمرینی پیدا نشد')}</h3><p>${t('Try a shorter search or another system.','عبارت کوتاه‌تر یا سیستم دیگری انتخاب کنید.')}</p></div>`}</div>`;}
function render(){let id=location.hash.slice(1);if(!screens.some(s=>s[0]===id))id='home';document.documentElement.lang=language;const d=document.getElementById('device');d.dir=language==='fa'?'rtl':'ltr';document.getElementById('offline').textContent=t('LOCAL / OFFLINE','محلی / آفلاین');let content='';
if(modules.some(m=>m[0]===id))content=overview(id);
else switch(id){
case 'splash':content=`<div class="splash center row" style="flex-direction:column">${document.querySelector('.emblem').outerHTML}<h1>NEUROX</h1><p>TRAIN YOUR MIND.<br>MASTER YOUR SPEED.</p><div class="foot">${button(t('Explore the experience','ورود به تجربه'),'onboarding')}<p class="sample">${t('Prototype navigation. No artificial startup delay in Android.','ناوبری نمونه؛ برنامهٔ Android تأخیر مصنوعی ندارد.')}</p></div></div>`;break;
case 'onboarding':content=`<div class="stepper"><span class="done"></span><span class="done"></span><span></span></div>${title('WELCOME TO NEUROX',t('A practice.<br>Entirely yours.','تمرینی برای شما.<br>فقط برای شما.'),t('Build attention, response, comprehension and typing skills. On your device. At your pace.','توجه، واکنش، درک و تایپ را با سرعت خودتان و روی دستگاه خودتان تمرین کنید.'))}<div class="panel">${section(t('Make yourself comfortable','تجربه را شخصی کنید'))}<div class="row spread"><p>Language / زبان</p><button class="chip" data-language>${language==='en'?'فارسی':'English'}</button></div><div class="row spread"><p>${t('Appearance','ظاهر')}</p><button class="chip" data-theme>${t('Switch theme','تغییر پوسته')}</button></div><div class="row spread"><p>${t('Reduced motion','حرکت کمتر')}</p><button class="toggle" aria-label="${t('Reduced motion','حرکت کمتر')}" aria-pressed="true"></button></div></div><div class="panel"><h3>${t('Private by design','حریم خصوصی از ابتدا')}</h3><p>${t('No account. No telemetry. No external AI. Your training stays local.','بدون حساب، رهگیری یا هوش مصنوعی بیرونی؛ تمرین شما محلی می‌ماند.')}</p></div>${button(t('Begin at my own pace','شروع با سرعت خودم'),'home')}${button(t('Explore the four systems','آشنایی با چهار سیستم'),'training',true)}`;break;
case 'home':content=`${title('YOUR DAILY PRACTICE',t('A sharper mind.<br>A steadier rhythm.','ذهنی دقیق‌تر.<br>ریتمی پایدارتر.'),t('A little focus goes a long way.','تمرین کوتاه، با توجه کامل.'))}<div class="panel hero-panel"><div class="row spread"><span class="pill gold">${t('TODAY · YOUR PACE','امروز · با سرعت خودتان')}</span><span class="muted">02 / 03</span></div><div class="metrics">${metric('12',t('Active minutes','دقیقهٔ فعال'))}${metric('05',t('Day streak','روز پیوسته'))}${metric('240',t('Experience','امتیاز تجربه'))}</div><div class="progress" style="--progress:66%"><span></span></div>${sample()}${button(t('Choose your next session','انتخاب جلسهٔ بعدی'),'training')}</div>${section(t('Four systems. One potential.','چهار مسیر، یک پتانسیل.'))}${moduleCards()}${section(t('A rhythm, not a race.','یک ریتم، نه مسابقه.'),t('This week','این هفته'))}<div class="panel">${week()}${sample()}</div>`;break;
case 'training':content=`${title('TRAINING / DISCOVER',t('What will you<br>practice today?','امروز چه چیزی<br>تمرین می‌کنید؟'),t('Choose a system. Read the instructions. Set a comfortable level.','یک سیستم انتخاب کنید، راهنما را بخوانید و سطح مناسب را تنظیم کنید.'))}${moduleCards()}<div class="panel"><h3>${t('Consistency before intensity.','پیوستگی پیش از شدت.')}</h3><p>${t('Take a short break between sessions. You can pause or stop at any time.','میان جلسات کمی استراحت کنید. هر زمان بخواهید می‌توانید مکث یا توقف کنید.')}</p>${button(t('Browse all exercises','همهٔ تمرین‌ها'),'library',true)}</div>`;break;
case 'vision-exercise':content=`<div class="module-vision">${title('VISION / FOCUS LOCK',t('Keep the target<br>in sight.','هدف را<br>در دید نگه دارید.'))}<div class="row spread"><span class="pill">${t('ROUND 2 / 5','دور ۲ از ۵')}</span><button class="chip" data-go="vision">${t('Pause & leave preview','مکث و خروج از نمونه')}</button></div><div class="training-grid">${Array.from({length:16},(_,i)=>`<button class="cell ${i===6?'target':''}" data-select-cell aria-label="${t('Grid cell','خانهٔ جدول')} ${i+1}">${i===6?'⊕':''}</button>`).join('')}</div><p>${t('Preview: choose a cell to inspect its selected state. This does not measure reaction time.','نمونه: با لمس خانه حالت انتخاب را ببینید؛ زمان واکنش اندازه‌گیری نمی‌شود.')}</p></div>`;break;
case 'reflex-exercise':content=`<div class="module-reflex">${title('REFLEX / CHOICE RESPONSE',t('Wait for the signal.','منتظر نشانه بمانید.'))}<div class="row spread"><span class="pill">${t('ROUND 1 / 5','دور ۱ از ۵')}</span><button class="chip" data-go="reflex">${t('Pause','مکث')}</button></div><div class="stimulus"><span class="signal">△</span><h3>${t('Match the shape','شکل مطابق را انتخاب کنید')}</h3><p class="sample">${t('STATIC INTERACTION PREVIEW','پیش‌نمایش ثابت تعامل')}</p></div><div class="chips">${['○','△','□'].map(x=>`<button class="chip" data-choice style="flex:1;font-size:28px">${x}</button>`).join('')}</div><p>${t('Preview only: selection changes appearance, not score.','فقط نمونه: انتخاب، ظاهر را عوض می‌کند نه امتیاز را.')}</p></div>`;break;
case 'reading-player':content=`${title('READ / RSVP STUDIO',t('One word.<br>Full attention.','یک واژه.<br>توجه کامل.'))}<div class="row spread"><span class="pill">${t('A ROOFTOP GARDEN','باغ روی بام')}</span><span class="muted">18 / 46</span></div><div class="stimulus"><span class="focus-word">${t('morn<b>i</b>ng','<b>آفتاب</b>')}</span><span class="pill">180 WPM · ${t('DESIGN SAMPLE','نمونهٔ طراحی')}</span></div><div class="progress" style="--progress:39%"><span></span></div><div class="row">${button(t('Back to studio','بازگشت به استودیو'),'read',true)}${button(t('View question layout','نمای پرسش'),'result')}</div><p>${t('Pace and comprehension remain separate. This prototype does not run a reading timer.','سرعت و درک جدا هستند. این نمونه تایمر خواندن اجرا نمی‌کند.')}</p>`;break;
case 'typing-exercise':content=`${title('TYPE / KEY PRECISION',t('Accuracy is<br>your foundation.','دقت،<br>پایهٔ سرعت است.'))}<span class="pill">${t('ROUND 1 / 5 · ENGLISH','دور ۱ از ۵ · انگلیسی')}</span><div class="panel" dir="ltr"><p>${t('TARGET TEXT','متن هدف')}</p><h2>Small steps build lasting skills.</h2></div><label><span class="muted">${t('Try the input style','نمونهٔ ورودی')}</span><input class="input" dir="ltr" maxlength="1000" placeholder="Small steps…" aria-label="${t('Typing preview','نمونهٔ تایپ')}"></label><div class="key-grid" dir="ltr">${'QWERTYUIOPASDFGHJKLZXCVBNM'.split('').map(x=>`<span class="key ${'ASDF'.includes(x)?'lit':''}">${x}</span>`).join('')}</div><p>${t('Keyboard illustration only. No draft, score or training session is saved.','تصویر صفحه‌کلید صرفاً نمونه است؛ متن، امتیاز یا جلسه ذخیره نمی‌شود.')}</p>${button(t('Back to typing studio','بازگشت به استودیو تایپ'),'type',true)}`;break;
case 'result':content=`${title('SESSION / REPORT',t('Every detail<br>tells a story.','هر جزئیات،<br>بخشی از نتیجه است.'))}<div class="panel hero-panel center"><span class="pill gold">${t('EXAMPLE COMPLETE SESSION','نمونهٔ جلسهٔ کامل')}</span><div class="ring"><strong>92%</strong><small>${t('Accuracy','دقت')}</small></div><h2>${t('Precision over pressure.','دقت، بدون فشار.')}</h2>${sample()}</div><div class="panel"><div class="metrics">${metric('284',t('Mean correct response','میانگین پاسخ درست'),'ms')}${metric('01',t('Incorrect response','پاسخ نادرست'))}${metric('0',t('Early taps','پاسخ زودهنگام'))}</div><p>${t('Only correct timed responses enter this latency average.','فقط زمان پاسخ‌های درست در این میانگین حساب می‌شود.')}</p></div>${button(t('Explore progress','بررسی پیشرفت'),'insights')}${button(t('Return home','خانه'),'home',true)}`;break;
case 'insights':content=`${title('PERFORMANCE / INSIGHTS',t('Progress,<br>with evidence.','پیشرفت،<br>با شواهد.'),t('Compare like with like. Your numbers need context.','شاخص‌های هم‌نوع را مقایسه کنید؛ هر عدد زمینهٔ خودش را دارد.'))}<div class="chips">${['7 days','30 days','Year'].map((x,i)=>`<button class="chip ${i===0?'active':''}" data-choice>${t(x,['۷ روز','۳۰ روز','سال'][i])}</button>`).join('')}</div><div class="panel">${section(t('Training rhythm','ریتم تمرین'),t('Active minutes','دقیقهٔ فعال'))}${week()}${sample()}</div><div class="panel"><div class="metrics">${metric('06',t('Valid sessions','جلسهٔ معتبر'))}${metric('51',t('Active minutes','دقیقهٔ فعال'))}</div></div>${modules.map(([id,n,en,fa])=>`<button class="module" data-module="${id}" data-go="${id}" style="min-height:90px"><span class="id">${id.toUpperCase()}</span><strong>${t(en,fa)}</strong><small>${t('Dedicated measures · history · recommendations','شاخص ویژه · سابقه · پیشنهاد')}</small></button>`).join('')}`;break;
case 'achievements':content=`${title('QUEST / MILESTONES',t('Small steps.<br>Real milestones.','گام‌های کوچک.<br>دستاوردهای واقعی.'),t('Progress without pressure. No lost-life mechanics.','پیشرفت بدون فشار؛ بدون جریمه برای استراحت.'))}<div class="panel hero-panel"><div class="metrics">${metric('01',t('Level','سطح'))}${metric('240',t('Total XP','امتیاز تجربه'))}</div><div class="progress" style="--progress:96%"><span></span></div>${sample()}</div>${[['01','First step','اولین گام','Complete one valid session','یک جلسهٔ معتبر کامل کنید'],['04','Four perspectives','چهار نگاه','Practice in every system','در هر چهار سیستم تمرین کنید'],['07','A steady week','یک هفتهٔ پایدار','Train on seven different days','در هفت روز متفاوت تمرین کنید']].map(([n,en,fa,desc,descfa],i)=>`<div class="panel"><div class="row"><span class="tag-icon medal">${n}</span><div><h3>${t(en,fa)}</h3><p>${t(desc,descfa)}</p></div></div><span class="pill">${i===0?t('EXAMPLE UNLOCKED','نمونهٔ بازشده'):t('EXAMPLE IN PROGRESS','نمونهٔ در حال پیشرفت')}</span></div>`).join('')}`;break;
case 'library':content=library();break;
case 'profile':content=`${title('NEUROX / IDENTITY',t('Your space.<br>Your practice.','فضای شما.<br>تمرین شما.'))}<div class="panel"><div class="row"><span class="tag-icon" style="width:64px;height:64px;font-size:28px">N</span><div><h2>${t('Local guest','مهمان محلی')}</h2><p>${t('No account required','بدون نیاز به حساب آنلاین')}</p></div></div><span class="pill gold">${t('ACTIVE PROFILE','پروفایل فعال')}</span></div><div class="panel"><h3>${t('A private training history','تاریخچه‌ای شخصی')}</h3><p>${t('Profiles separate local preferences and sessions. PIN protection is a separate security feature, not implied by this design.','پروفایل‌ها تنظیمات و جلسات را جدا می‌کنند. قفل PIN قابلیتی مستقل است و از این نمونه استنباط نمی‌شود.')}</p>${button(t('Preferences','تنظیمات'),'settings',true)}${button(t('Milestones','دستاوردها'),'achievements',true)}</div>`;break;
case 'settings':content=`${title('PREFERENCES',t('Designed<br>around you.','مطابق<br>با شما.'))}<div class="panel">${section(t('APPEARANCE & ACCESS','ظاهر و دسترس‌پذیری'))}<div class="row spread"><div><h3>${t('Theme','پوسته')}</h3><p>${t('Dark, light, intentional','تیره، روشن، خوانا')}</p></div><button class="chip" data-theme>${t('Switch','تغییر')}</button></div><div class="divider"></div><div class="row spread"><h3>Language / زبان</h3><button class="chip" data-language>${language==='en'?'فارسی':'English'}</button></div><div class="divider"></div><div class="row spread"><h3>${t('Reduced motion','حرکت کمتر')}</h3><button class="toggle" aria-label="${t('Reduced motion','حرکت کمتر')}" aria-pressed="true"></button></div></div><div class="panel">${section(t('YOUR DATA','داده‌های شما'))}<p>${t('Offline training. No telemetry. Local profiles.','تمرین آفلاین، بدون رهگیری، با پروفایل محلی.')}</p>${button(t('Backup & restore design','طراحی پشتیبان و بازیابی'),'vault',true)}${button(t('View error & empty states','خطا و دادهٔ خالی'),'states',true)}</div>`;break;
case 'vault':content=`${title('VAULT / DATA CONTROL',t('Your data.<br>Your custody.','دادهٔ شما.<br>در اختیار شما.'),t('Explicit files. Authenticated encryption. A verified restore before any commit.','فایل مشخص، رمزنگاری احرازشده و تأیید بازیابی پیش از ثبت.'))}<div class="panel"><span class="pill gold">${t('DESIGN SPECIFICATION','مشخصات طراحی')}</span><h2>${t('Encrypted export','خروجی رمزنگاری‌شده')}</h2><p>${t('Select a destination with Android’s file picker. Enter a new password. Do not store the password.','مقصد را با انتخابگر Android تعیین کنید و گذرواژهٔ تازه وارد کنید؛ گذرواژه ذخیره نمی‌شود.')}</p><button class="button secondary" disabled>${t('Requires Android SAF implementation','نیازمند پیاده‌سازی SAF در Android')}</button></div><div class="panel"><h2>${t('Restore with confidence','بازیابی با تأیید')}</h2>${['Select file → authenticate','Validate schema and references','Preview profiles and sessions','Confirm → transactional commit'].map((x,i)=>`<div class="row"><span class="tag-icon">${i+1}</span><p>${t(x,['انتخاب فایل و احراز اصالت','اعتبارسنجی ساختار و ارجاع‌ها','پیش‌نمایش پروفایل و جلسه','تأیید و ثبت تراکنشی'][i])}</p></div>`).join('')}<p class="sample">${t('No encryption or restore is simulated here. Android integration remains open.','هیچ رمزنگاری یا بازیابی نمایشی اجرا نمی‌شود؛ یکپارچه‌سازی Android باقی است.')}</p></div>`;break;
case 'states':content=`${title('SYSTEM / HONEST STATES',t('Clarity,<br>even when it fails.','شفافیت،<br>حتی هنگام خطا.'))}<div class="panel"><span class="pill">${t('EMPTY HISTORY','تاریخچهٔ خالی')}</span><h2>${t('Your progress starts here.','مسیر شما از اینجا شروع می‌شود.')}</h2><p>${t('No measured sessions yet. Nothing is invented to fill this chart.','هنوز جلسه‌ای اندازه‌گیری نشده است؛ نمودار با دادهٔ ساختگی پر نمی‌شود.')}</p>${button(t('Explore training','انتخاب تمرین'),'training')}</div><div class="panel"><span class="pill error">${t('STORAGE ERROR · DESIGN EXAMPLE','خطای ذخیره · نمونهٔ طراحی')}</span><h2>${t('Your previous data stays safe.','دادهٔ قبلی حفظ می‌شود.')}</h2><p>${t('Pause training. Explain the failed operation. Keep the original data. Offer a real retry in Android.','تمرین را متوقف کنید، خطا را توضیح دهید و دادهٔ اصلی را نگه دارید. تلاش دوباره باید واقعی باشد.')}</p>${button(t('Return to design home','خانهٔ نمونه'),'home',true)}</div>`;break;
}
document.getElementById('screen').innerHTML=`<section class="page" data-screen="${id}">${content}</section>`;
document.getElementById('screenSelect').value=id;
document.querySelectorAll('#screenIndex button').forEach(b=>b.classList.toggle('active',b.dataset.go===id));
document.getElementById('bottomNav').innerHTML=[['home','Home','خانه'],['training','Train','تمرین'],['insights','Insights','تحلیل'],['library','Library','کتابخانه'],['profile','You','شما']].map(([key,en,fa])=>`<button data-go="${key}" class="${key===id?'active':''}">${icon(key)}<span>${t(en,fa)}</span></button>`).join('');
document.getElementById('bottomNav').style.display=['splash','vision-exercise','reflex-exercise','reading-player','typing-exercise'].includes(id)?'none':'flex';
document.querySelector('.appbar').style.display=id==='splash'?'none':'flex';
}
function toggleTheme(){let root=document.documentElement;root.dataset.theme=root.dataset.theme==='dark'?'light':'dark';document.getElementById('theme').textContent=root.dataset.theme==='dark'?'Light theme':'Dark theme';}
function toggleLanguage(){language=language==='en'?'fa':'en';document.getElementById('language').textContent=language==='en'?'فارسی':'English';render();}
document.getElementById('screenSelect').innerHTML=screens.map(([id,en],i)=>`<option value="${id}">${String(i+1).padStart(2,'0')} · ${en}</option>`).join('');
document.getElementById('screenIndex').innerHTML=screens.map(([id,en],i)=>`<button data-go="${id}">${String(i+1).padStart(2,'0')} &nbsp; ${en}</button>`).join('');
document.getElementById('screenSelect').onchange=e=>location.hash=e.target.value;
document.getElementById('direction').onchange=e=>document.documentElement.dataset.direction=e.target.value;
document.getElementById('theme').onclick=toggleTheme;document.getElementById('language').onclick=toggleLanguage;
document.getElementById('scale').onclick=()=>document.body.classList.toggle('large');
document.addEventListener('click',e=>{let target=e.target.closest('[data-go],[data-theme],[data-language],[data-filter],[data-choice],[data-select-cell],.toggle');if(!target)return;if(target.dataset.go){location.hash=target.dataset.go;return;}if(target.hasAttribute('data-theme'))toggleTheme();else if(target.hasAttribute('data-language'))toggleLanguage();else if(target.hasAttribute('data-filter')){filter=target.dataset.filter;render();}else if(target.classList.contains('toggle'))target.setAttribute('aria-pressed',String(target.getAttribute('aria-pressed')!=='true'));else if(target.hasAttribute('data-select-cell')){document.querySelectorAll('.cell').forEach(x=>x.classList.remove('target'));target.classList.add('target');}else {target.parentElement.querySelectorAll('.chip').forEach(x=>x.classList.remove('active'));target.classList.add('active');}});
document.addEventListener('input',e=>{if(e.target.id==='search'){let pos=e.target.selectionStart;query=e.target.value;render();const input=document.getElementById('search');input.focus();input.setSelectionRange(pos,pos);}});
window.addEventListener('hashchange',render);render();
